import itertools
import random

def count_max_edges_subgraph(adj, k):
    max_e = 0
    for nodes in itertools.combinations(range(len(adj)), k):
        e = 0
        for i in range(len(nodes)):
            for j in range(i + 1, len(nodes)):
                if adj[nodes[i]][nodes[j]]:
                    e += 1
        if e > max_e:
            max_e = e
        if max_e > 15:
            return max_e
    return max_e

def solve():
    N = 15
    E = 56
    K = 8

    # Let's try a circulant graph C(15, S) and then add edges.
    # Or even better, let's just use a more systematic way to add edges.
    for S_size in range(1, 8):
        for _ in range(100):
            S = random.sample(range(1, 8), S_size)
            adj = [[0]*N for _ in range(N)]
            for i in range(N):
                for s in S:
                    j = (i + s) % N
                    adj[i][j] = adj[j][i] = 1

            current_edges = sum(sum(row) for row in adj) // 2
            if current_edges > E:
                continue

            remaining = E - current_edges
            all_pairs = list(itertools.combinations(range(N), 2))
            random.shuffle(all_pairs)
            for u, v in all_pairs:
                if adj[u][v] == 0:
                    adj[u][v] = adj[v][u] = 1
                    remaining -= 1
                    if remaining == 0:
                        break

            if count_max_edges_subgraph(adj, K) <= 15:
                print(f"Found! Max edges: {count_max_edges_subgraph(adj, K)}")
                return

solve()

